		p1Total += score
		if score >= 8 {
			p1High++
		}
	}
	for _, score := range player2 {
		p2Total += score
		if score >= 8 {
			p2High++
		}
	}

	fmt.Println("Player 1 total: " + fmt.Sprint(p1Total))
	fmt.Println("Player 2 total: " + fmt.Sprint(p2Total))

