		winner = "Player 2"
	}
	fmt.Println("Winner: " + winner)
	fmt.Println("P1 rounds 8+: " + fmt.Sprint(p1High))
	fmt.Println("P2 rounds 8+: " + fmt.Sprint(p2High))
