import "fmt"

func main() {
	temps := []int{22, 18, 25, 31, 29, 17, 24, 28, 20, 26}

	count := len(temps)
	sum := 0
	hot := 0
	mild := 0
	cold := 0

	for _, t := range temps {
		sum = sum + t
		if t >= 28 {
			hot++
		} else if t >= 20 {
			mild++
		} else {
			cold++
		}
	}

	avg := sum / count

	if hot+mild+cold != count {
		panic("category counts do not sum to total count")
	}

	if avg != 24 {
		panic("average is not 24")
	}

	fmt.Println("Days measured: " + fmt.Sprint(count))
	fmt.Println("Average: " + fmt.Sprint(avg))
	fmt.Println("Hot days (28+): " + fmt.Sprint(hot))
	fmt.Println("Mild days: " + fmt.Sprint(mild))
	fmt.Println("Cold days (<20): " + fmt.Sprint(cold))
}

